import { createForks, teardownForks } from '@tigrisdata/agent-kit';
import { S3Client, PutObjectCommand, ListObjectsV2Command } from '@aws-sdk/client-s3';
import * as fs from 'fs/promises';

async function main() {
  const adminAccessKeyId = process.env.TIGRIS_STORAGE_ACCESS_KEY_ID;
  const adminSecretAccessKey = process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY;

  if (!adminAccessKeyId || !adminSecretAccessKey) {
    throw new Error('Admin credentials missing');
  }

  const forkSet = await createForks('gold-source', 3, {
    prefix: 'audit-fork',
    credentials: { role: 'Editor' },
  });

  if (forkSet.error) {
    throw new Error(`Failed to create forks: ${forkSet.error.message}`);
  }

  try {
    const uploadPromises = forkSet.forks.map((fork, index) => {
      const s3Client = new S3Client({
        region: 'REDACTED',
        endpoint: 'REDACTED',
        credentials: {
          accessKeyId: fork.credentials.accessKeyId,
          secretAccessKey: fork.credentials.secretAccessKey,
        },
      });
      const key = `agent-${index + 1}.out`;
      return s3Client.send(
        new PutObjectCommand({
          Bucket: fork.bucket,
          Key: key,
          Body: `Output from agent ${index + 1}`,
        })
      );
    });

    await Promise.all(uploadPromises);

    const adminS3Client = new S3Client({
      region: 'REDACTED',
      endpoint: 'REDACTED',
      credentials: {
        accessKeyId: adminAccessKeyId,
        secretAccessKey: adminSecretAccessKey,
      },
    });

    const goldSourceList = await adminS3Client.send(
      new ListObjectsV2Command({ Bucket: 'gold-source' })
    );

    const source_keys = (goldSourceList.Contents || []).map((c) => c.Key!).sort();
    if (source_keys.length !== 2 || source_keys[0] !== 'seed1.txt' || source_keys[1] !== 'seed2.txt') {
      throw new Error(`gold-source does not contain exactly seed1.txt and seed2.txt. Found: ${source_keys.join(', ')}`);
    }

    const fork_results = [];
    for (let i = 0; i < forkSet.forks.length; i++) {
      const fork = forkSet.forks[i];
      const s3Client = new S3Client({
        region: 'REDACTED',
        endpoint: 'REDACTED',
        credentials: {
          accessKeyId: fork.credentials.accessKeyId,
          secretAccessKey: fork.credentials.secretAccessKey,
        },
      });

      const forkList = await s3Client.send(
        new ListObjectsV2Command({ Bucket: fork.bucket })
      );

      const keys = (forkList.Contents || []).map((c) => c.Key!).sort();
      fork_results.push({
        bucket: fork.bucket,
        keys,
      });

      const expectedAgentOut = `agent-${i + 1}.out`;
      const expectedKeys = ['seed1.txt', 'seed2.txt', expectedAgentOut].sort();

      if (keys.length !== 3 || JSON.stringify(keys) !== JSON.stringify(expectedKeys)) {
        throw new Error(`Fork ${fork.bucket} keys mismatch. Expected: ${expectedKeys.join(', ')}. Found: ${keys.join(', ')}`);
      }
    }

    const report = {
      source_keys,
      fork_results,
    };

    await fs.writeFile('/home/user/isolation/audit.json', JSON.stringify(report, null, 2), 'utf-8');
  } finally {
    await teardownForks(forkSet);
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

