import { S3Client, DeleteBucketCommand, DeleteObjectCommand, ListObjectsV2Command } from '@aws-sdk/client-s3';
const s3 = new S3Client({
  region: 'REDACTED',
  endpoint: 'REDACTED',
  credentials: {
    accessKeyId: process.env.TIGRIS_STORAGE_ACCESS_KEY_ID!,
    secretAccessKey: process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY!,
  },
});
async function run() {
  for (const bucket of ['audit-fork-0', 'audit-fork-1', 'audit-fork-2']) {
    try {
      const list = await s3.send(new ListObjectsV2Command({ Bucket: bucket }));
      for (const obj of list.Contents || []) {
        await s3.send(new DeleteObjectCommand({ Bucket: bucket, Key: obj.Key }));
      }
      await s3.send(new DeleteBucketCommand({ Bucket: bucket }));
      console.log(`Deleted ${bucket}`);
    } catch (e) {
      console.error(`Failed to delete ${bucket}:`, e);
    }
  }
}
run().catch(console.error);
